        if (pickedUnits > order.Lines.Sum(line => line.Quantity)) return "over-pick";
        _pickNotes[order.Reference] = "confirmed";
        return order.Priority ? "confirmed-priority" : "confirmed";
    }

    public string ChooseCarrier(OrderRequest order, IEnumerable<CarrierOption> carriers)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (string.IsNullOrWhiteSpace(order.Country)) return "country-required";
        if (order.Lines.Count == 0) return "empty-order";
        var eligible = carriers.Where(carrier => carrier.Countries.Contains(order.Country)).ToList();
        if (eligible.Count == 0) return "no-country-service";
        if (order.Lines.Any(line => line.Fragile)) eligible = eligible.Where(carrier => carrier.HandlesFragile).ToList();
        if (eligible.Count == 0) return "no-fragile-service";
        if (order.Priority) eligible = eligible.Where(carrier => carrier.TransitDays <= 2).ToList();
        if (eligible.Count == 0) return "no-priority-service";
        var selected = eligible.OrderBy(carrier => carrier.Price).ThenBy(carrier => carrier.TransitDays).First();
        _routes[order.Reference] = selected.Code;
        return selected.Code;
    }

    public string Dispatch(OrderRequest order, string labelCode, bool handoverAccepted)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (!_routes.ContainsKey(order.Reference)) return "route-missing";
        if (string.IsNullOrWhiteSpace(labelCode)) return "label-required";
        if (!labelCode.StartsWith(_routes[order.Reference], StringComparison.Ordinal)) return "label-route-mismatch";
        if (!handoverAccepted) return "handover-rejected";
        if (order.Lines.Count == 0) return "invalid-order";
        if (order.Lines.Any(line => line.Quantity <= 0)) return "invalid-quantity";
        _routes[order.Reference] = "dispatched:" + labelCode;
        return order.Priority ? "dispatched-priority" : "dispatched";
    }

    public string RegisterException(OrderRequest order, WarehouseException exception)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (string.IsNullOrWhiteSpace(exception.Code)) return "invalid-code";
        if (exception.Severity is not ("low" or "medium" or "high")) return "invalid-severity";
        if (exception.StockRelated && order.Lines.Count == 0) return "stock-context-required";
        if (exception.CustomerVisible && string.IsNullOrWhiteSpace(order.Country)) return "customer-context-required";
        if (_exceptions.ContainsKey(order.Reference)) return "exception-already-open";
        _exceptions[order.Reference] = exception.Code;
        return "registered";
    }

    public string ResolveException(OrderRequest order, WarehouseException exception, string resolution)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (!_exceptions.ContainsKey(order.Reference)) return "exception-not-open";
        if (_exceptions[order.Reference] != exception.Code) return "exception-mismatch";
        if (string.IsNullOrWhiteSpace(resolution)) return "resolution-required";
        if (exception.Severity == "high" && resolution.Length < 8) return "resolution-too-short";
        if (exception.StockRelated && resolution == "ignore") return "stock-resolution-required";
        _exceptions.Remove(order.Reference);
        return "resolved";
    }
}

